window.RIDOH_NH_REPORTS={"updated":"2026-11-08","homes":{"LTC00774":{"name":"Brookdale Sakonnet Bay","reports":[{"date":"2025-06-24","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1eGn5FTxfRdPGv-hrkNiN2e8N0BbZWvqk/view"},{"date":"2025-06-18","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1_UBk-h7Th0BLFmWeIz8I32IagAq6-rYb/view"},{"date":"2025-05-14","type":"Annual inspection","no_findings":false,"tier":"most_serious","headline":"Resident fell repeatedly, then needed six stitches; fall plan never updated","paragraphs":["M595: Repeated falls not prevented / A resident with dementia fell at least seven times between March 6 and May 9, 2025. After the last fall the resident was found on the floor in a pool of blood and needed six stitches in the forehead at the hospital. The care plan listed no way to prevent falls other than a floor mat, the fall-risk sign was not posted, and the plan was not updated after each fall.","M595: Wound care not done safely / On May 13, 2025, a nurse used the same gloves on two of a resident's wounds and spread the wound treatment with her gloved hand instead of an applicator.","M595: Sedating medicine continued without review / A resident with dementia was given an as-needed gel containing Ativan, Benadryl, and Haldol for agitation on April 9, April 13, and May 3, 2025. The order was supposed to be re-evaluated on March 5, 2025, and never was.","M015/M016/M018/M019: Program to prevent lifting injuries incomplete / The home's safe resident handling program was missing required parts: a hazard assessment, a policy on when lifting aids should not be used, a yearly evaluation, and a yearly report to its safe handling committee."],"link":"https://drive.google.com/file/d/1hwCosbNvqV0AfBUIMMexV-VOZ5TfbVRY/view"},{"date":"2025-03-20","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1EC5cgjnyvQ8HSz3NsvFkb6pF9nhNsean/view"},{"date":"2025-02-10","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/14L1aP_4PHZ56FokDjLgeq0NZ_iYPc7uq/view"},{"date":"2025-01-03","type":"Complaint investigation","no_findings":false,"tier":"serious","headline":"Nurse with COVID-19 worked a full shift caring for residents","paragraphs":["M635: Nurse with COVID-19 worked with residents / A registered nurse tested positive for COVID-19 on December 27, 2024, and worked that day from 3 PM to 4 AM, giving medicine to residents and checking on them. The home did not follow its own rules for when staff with COVID-19 may return to work.","M645: COVID-19 cases not reported to RIDOH / The home did not tell RIDOH that two nurses tested positive for COVID-19, on December 8 and December 27, 2024, as required."],"link":"https://drive.google.com/file/d/1U2uU0kz2kKWscS8goPUbjp97jtvrtAMQ/view"},{"date":"2024-12-10","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1K05lr0arepS6DO1brSWKNPz8MRROzJA7/view"},{"date":"2024-05-09","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1LPWAz-IC9bQn9fmYi1UEARNPrQsVAt5k/view"},{"date":"2024-03-22","type":"Annual inspection","no_findings":false,"tier":"most_serious","headline":"Dialysis resident missed blood thinner, insulin, and other medicines","paragraphs":["M790: Medicines not given as ordered / A resident on dialysis three times a week did not get ordered medicines on several days in March 2024, including the blood thinner Eliquis on March 13 and 21, the water pill furosemide on four days, and insulin on March 18. There was no record that the doctor was told.","M186: COVID-19 precautions not followed during an outbreak / Seven residents had COVID-19. On March 20 and 21, 2024, front desk staff did not screen visitors or inspectors, and staff and a visitor went onto the unit without N95 masks. A nursing assistant went into a COVID-positive resident's room without eye protection, and a fan blew air from the nurses' station into the residents' hallway.","M870: Weight loss not reported / A resident lost 5.2 pounds in one week in March 2024, from 121.2 to 116 pounds, a significant loss. The nurse did not know, and there was no record that the dietitian or doctor was told or that anything was done.","M690: Doctor's exam late after admission / Two residents did not get a physical exam until six days after they were admitted. The rule is within 48 hours.","M1055: Leg brace used without an order or plan / A resident with dementia had worn an ankle-foot brace every day since October 2023 with no doctor's order and nothing about it in the care plan."],"link":"https://drive.google.com/file/d/16gNdISH1Af988srfOfvh1pYscqAwrOxm/view"},{"date":"2023-12-21","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1k57c6_smr7IX_IdX8FD0wYEw3SWSsxLo/view"},{"date":"2023-11-27","type":"Complaint investigation","no_findings":false,"tier":"most_serious","headline":"Resident told to wait for the bathroom, pushed to dinner, fell","paragraphs":["M365: Resident not treated with dignity, then injured / On November 23, 2023, a resident who is at risk for falls and takes a blood thinner asked to use the bathroom before dinner. A nursing assistant said the resident had to wait until after dinner and pushed the resident to the dining room in a wheelchair while the resident screamed for her to stop. The resident's foot went under the wheelchair, the resident fell forward onto the floor, and was sent to the hospital with a scrape on the nose and bruises on the head and hand. The home had no rule against using the bathroom at mealtime."],"link":"https://drive.google.com/file/d/1gNVtRkShe772tBev1RNLR72DzZzUWB2j/view"},{"date":"2023-08-16","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1CeN5oaDlkTupoTaznFCfVvTE0zT5L6d2/view"},{"date":"2023-04-25","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1sV2XIVY7R81GTf8Q6lK0qkMvbnirLHAI/view"},{"date":"2023-04-05","type":"Annual inspection","no_findings":false,"tier":"minor","headline":"Expired supplies, undated food, and a staff evaluation not done","paragraphs":["M935: Expired and unlabeled medicines and supplies / On April 4 and 5, 2023, inspectors found a vial of lidocaine with no resident's name, needles that expired September 30, 2022, urine cups and wipes that expired in January 2023, and an opened bottle of CBD drops with no date or resident's name on a medication cart. An opened nasal spray had no date.","M880: Food not dated or kept too long / About 50 small containers of sour cream and 40 of cranberry sauce made on March 28 were still in the kitchen 8 days later; the limit is 7 days. Forty-one thawed nutrition shakes in a unit kitchenette had no date.","M810: Medication technician not evaluated / A medication technician hired in February 2022 had not had the required quarterly evaluation since September 2022."],"link":"https://drive.google.com/file/d/142r3Y1p3AhAChqYKCzqhKGRyir9JPjR_/view"}]},"LTC00777":{"name":"Brookdale South Bay","reports":[{"date":"2026-06-17","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1Cvz7vz59a3Yk6rJ9bUzSunnjGxPoCAPB/view"},{"date":"2026-02-05","type":"Annual inspection and complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1RrlJL0oiFVtPTbIWJ06mA9__DQ3MCEZ3/view"},{"date":"2025-06-12","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1HKb1yGJl1TOm4-9ka9yT_6zUAvmJibYn/view"},{"date":"2025-05-07","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1xZeyAXiUMNs9jKWwvfDyljtBArFCgw1Z/view"},{"date":"2025-04-09","type":"Annual inspection and complaint investigation","no_findings":false,"tier":"serious","headline":"Not enough CPR-certified staff on four days; infection precautions skipped","paragraphs":["M715: Not enough CPR-certified staff / On 4 of 8 days checked (April 2, 3, 4, and 8, 2025), the home did not have two staff certified in CPR available around the clock, as required.","M630: Infection precautions not followed / A resident with a pressure sore was not on the required gown-and-glove precautions, and staff went in to care for the resident without gowns. For another resident isolated for a drug-resistant urine infection, a nurse set wound supplies on a bedside table without first making a clean surface.","M210: Staff vaccine records missing / Four of seven new staff had no record of a flu shot or a signed refusal.","M010/M015: Program to prevent lifting injuries incomplete / Too few members of the safe resident handling committee were hourly direct-care staff, and the yearly report was not done.","M1305: Emergency generator testing not shown / There was no proof that the monthly generator test reached the required load in any of the last 12 months."],"link":"https://drive.google.com/file/d/1MYlZAsT4vlZRlXZ7BiGVSfee-OtfpFgC/view"},{"date":"2024-10-22","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1hR1pHD0b1VZa0t2KX0U8IxTFM4-ZOvIy/view"},{"date":"2024-10-01","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1_2Zbz15NXP_6RZ8dYiEx840b6IsDOiS3/view"},{"date":"2024-09-05","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1NQKUy1gUZWIap_ovgZUnd2iD7xxw9H-h/view"},{"date":"2024-05-10","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1IA6_8_cHKDlVSI1IS23y5R8hwDLExP0V/view"},{"date":"2024-03-27","type":"Annual inspection and complaint investigation","no_findings":false,"tier":"most_serious","headline":"Dialysis resident missed a medicine on 12 days; pressure sores untreated","paragraphs":["M790: Dialysis resident's medicine missed / A resident on dialysis was supposed to get sevelamer, a medicine that controls phosphorus, three times a day. The noon dose was charted as not given on 12 dialysis days in March 2024 because the resident was out, and the doctor was not told.","M780: Pressure sores not treated / A nurse found an open area on a resident's tailbone on March 23, 2024, but no one told the doctor or started treatment. Two days later it was a stage 2 pressure sore, 2 cm by 2 cm. Another resident had an open sore on the ankle with no treatment order, and staff did not know about it.","M630: Infection precautions stopped too soon / A resident with a catheter was hospitalized in February 2024 with blood in the urine and came back with MRSA, a drug-resistant staph infection. The home stopped isolation precautions without the repeat test its rules require, and an aide caring for the resident did not know about the infection.","M595: Dialysis and catheter care not checked / There was no order to check a dialysis resident's access site every shift, and forms to the dialysis center were not sent on six dates in March 2024. Urine output was not recorded for two residents with catheters about a third of the time (28 and 26 of 75 times).","M880: Kitchen problems / The walk-in freezer had a foamy substance hanging from the ceiling, a sticky spill, and unlabeled food with freezer burn. Jello was kept past its use-by date."],"link":"https://drive.google.com/file/d/159Av43rhKjxUR87V74X55yK2M4XMhgIQ/view"},{"date":"2023-05-05","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1j_uOE9OtTbA8z61YNp1HjW2Berexra-k/view"},{"date":"2023-04-06","type":"Annual inspection and complaint investigation","no_findings":false,"tier":"most_serious","headline":"Resident missed evening medicines, including a blood thinner","paragraphs":["M790: Evening medicines not given / A resident with multiple sclerosis and a history of blood clots did not get any of the evening medicines ordered for April 2, 2023, including the blood thinner Coumadin. There was no evidence they were given.","M755: Care plan not followed; sore skin not reported / The same resident's care plan called for a pressure-relief cushion, but on April 4 and 5, 2023, inspectors saw the resident sitting in a recliner for hours without one. The resident said their bottom hurt, aides did not know about the plan, and redness on the buttocks had not been reported. The plan also called for checking the resident's lungs, swelling, and weight, which was not done, and the resident had moderate swelling in both legs.","M595: Monthly weights not done / The resident's doctor ordered monthly weights in January 2023. None were taken in February or March.","M880: Kitchen problems / Food and trash were on the walk-in freezer floor, two rusted nails held the ice machine's inside shield, a dietary worker had no hair covering, and water pitchers were stored on the floor."],"link":"https://drive.google.com/file/d/1Ji3p1NtL5TjLu5nyo1uQ5U599T0JcbMo/view"}]},"LTC00682":{"name":"Rhode Island Veterans Home","reports":[{"date":"2026-06-25","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1_y01KTyV00GgrhkvYPKzo51YUnMKjKJ7/view"},{"date":"2026-04-21","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1PphSrKzlO9E4FkMYwtdghFSyvzzQv8r-/view"},{"date":"2026-02-05","type":"Annual inspection and complaint investigation","no_findings":false,"tier":"serious","headline":"Fluid limit for a resident with heart failure not tracked","paragraphs":["M595: Fluid limit not followed / A resident with heart failure had a doctor's order to drink no more than 1.5 liters a day. No one totaled what the resident drank. On February 5, 2026, there were 40 ounces of bottled water at the bedside under a \"fluid restriction\" sign, and the resident said staff sometimes said to drink more.","M880: Kitchen problems / Three kitchen staff, including the food service director, did not have current food safety certification. The dish machine water was not hot enough to sanitize (152 and 148 degrees; it must be 160), and all five unit kitchenettes had unlabeled, undated food.","M215: Staff vaccine records missing / Seven of seven staff checked had no record of a flu or hepatitis B vaccine or a signed refusal.","M085: Quality committee missing members / Required members, such as the medical director or the social worker, missed the quality committee's meetings in June, September, and December 2025."],"link":"https://drive.google.com/file/d/138PuNeIcA38QtLKca9Amovjw5MBtMMqg/view"},{"date":"2025-11-10","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1rOrADUcnYi4DvQQlb8EsdWMnQRxOg4mb/view"},{"date":"2025-10-20","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1nT54AcXtPrRKyFaTxlj1tF_xeHgBcokP/view"},{"date":"2025-07-11","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1q1J4hhRnpIIwxiuXSzbhzg1R39uQY22i/view"},{"date":"2025-06-16","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1GKium-rfpWaEVNk6nQ5lsRiknQb-OPz5/view"},{"date":"2025-06-09","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1keRZpsi2N-MjzfqgbWzJdWBoL1gY_DgC/view"},{"date":"2025-05-01","type":"Annual inspection and complaint investigation","no_findings":false,"tier":"most_serious","headline":"Heart and blood pressure medicines wrongly held, doctor not told","paragraphs":["M595: Medicines held against the doctor's orders / A resident with kidney disease was to get heart and blood pressure medicines unless pulse or blood pressure fell below set limits. Nurses held amiodarone on April 5, 2025, amlodipine on April 5 and 19, and furosemide on April 8, though the readings were within the limits, and the doctor was not told."],"link":"https://drive.google.com/file/d/12S5YFiWcVnNkTNfXQZpgGgjMeIlC8dD8/view"},{"date":"2024-09-25","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1NEc0FrH5EE3U96SguczHSYLcMFaTDr2p/view"},{"date":"2024-08-01","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1AzBFaCBuxG553GiVKJXFrwWgkSnxuafK/view"},{"date":"2024-07-31","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1ZA4gnfDzwngyB1VIt38EbyjM7Ip6OpMU/view"},{"date":"2024-05-10","type":"Complaint investigation","no_findings":false,"tier":"serious","headline":"Aide moved a resident alone with a two-person lift","paragraphs":["M200: Mechanical lift used by one aide / On May 9, 2024, an inspector heard a resident with dementia shouting \"no\" and moaning. A nursing assistant had moved the resident into bed with a Hoyer lift by himself, though the home's policy requires two staff for safety."],"link":"https://drive.google.com/file/d/1fOyynU0WvE-DeSiI8dBF9XfnQG-QW4jL/view"},{"date":"2024-04-24","type":"Annual inspection and complaint investigation","no_findings":false,"tier":"serious","headline":"Fall mats missing for a resident at risk of injury","paragraphs":["M595: Fall mats missing / A resident with dementia and a history of falls with injury had a doctor's order for a low bed with mats on the floor at all times. On April 23, 2024, inspectors saw no mats three times while the resident was in bed, though a nurse had signed that the order was done.","M935: Expired and unlabeled medicines / In three of five medication rooms and one medication cart, inspectors found creams that had expired as far back as July 2023, expired syringes, eye drops and an inhaler past their use-by dates, and creams with missing or unreadable labels.","M010: No committee to prevent lifting injuries / The safe resident handling committee had not met since August 23, 2022."],"link":"https://drive.google.com/file/d/1jYmc7V4oComUcObAEpQNkua84pfNUbdr/view"},{"date":"2024-03-11","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1newCfbNhUy3livYLVUmbgJlIgh65obUz/view"},{"date":"2024-01-05","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1OLlRXnRlFYJN-gIRBToBFJ243-b5LNP3/view"},{"date":"2023-08-03","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/19nf66tZspgShPPCZm5DePbD-ndaKlX99/view"},{"date":"2023-07-11","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1S0FBLpXhyKNbQKZCunXq9Zx4yXHUhAI0/view"},{"date":"2023-05-12","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1RLnYsoIVBeVJdFVGw4l-LFOuAnF23_qm/view"},{"date":"2023-04-20","type":"Annual inspection and complaint investigation","no_findings":false,"tier":"serious","headline":"Urine output not tracked for residents with kidney problems","paragraphs":["M595: Catheter care not documented / Two residents with urinary catheters, both with kidney problems, had no urine output recorded for 41 and 38 of 57 times between April 1 and 19, 2023. One resident's doctor had ordered a bladder scan if output was low, and there was no record the order was followed.","M880: Kitchen problems / Cooks did not wear beard covers, pureed meatloaf was served at 105.6 degrees (it must be 135), thickener scoops were left in the powder, a thermometer was wiped with a dirty cloth, and a bottle of sanitizer was labeled peroxide."],"link":"https://drive.google.com/file/d/1C7lkMuvecXBX0tHBrt83xk4XGeImLKLP/view"},{"date":"2023-02-23","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1fNtTAflRat6M-FEKC5lvLKI1wx0ZkPGX/view"}]},"LTC00722":{"name":"Village at Waterman Lake","reports":[{"date":"2025-10-16","type":"Annual inspection","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1PfoA7dsFoNPKGMCAaflQZ9USBExxXW01/view"},{"date":"2025-10-02","type":"Complaint investigation","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/1sJbbNjKH6GUEkQ6nc8wBbEbgx2SLD01q/view"},{"date":"2024-11-26","type":"Annual inspection","no_findings":true,"tier":null,"headline":"No deficiencies identified","paragraphs":[],"link":"https://drive.google.com/file/d/19aUaAuVZIXvlPTEnCKm3bBxWOgPFf4ZO/view"},{"date":"2024-02-07","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1_sVZY5seul_uhf9aH6GWk_9acJxr1V8Z/view"},{"date":"2023-12-07","type":"Annual inspection","no_findings":false,"tier":"most_serious","headline":"Two residents lost weight; doctor and dietitian not told","paragraphs":["M710: Weight loss not reported / One resident with Alzheimer's disease lost 10 pounds between October 1 and December 1, 2023, and another lost 9.2 pounds in less than a month. Neither the doctor nor the dietitian was told. Inspectors saw one resident asleep at lunch three days in a row while staff took the tray away without helping, and the meal was charted as refused.","M755: Care plans not updated / One resident's care plan still listed a pressure sore that had healed in August, and another's was not updated after significant weight loss.","M860: Dietitian duties not done / The dietitian had not reviewed the fall and winter menus, there were no recipes or nutrition analysis for the meals, and staff did not get regular training.","M880: Kitchen problems / Food was stored on the walk-in floor, shelving had buildup, and opened food was not labeled or dated."],"link":"https://drive.google.com/file/d/1ASlsLf11gImZUEIMrrNWdBERnJ1nPpzz/view"},{"date":"2023-10-13","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/1Z5Go4MpYByPa-4ZzkQnQyxogTCLBEJbL/view"},{"date":"2023-09-26","type":"Complaint investigation","no_findings":false,"tier":"most_serious","headline":"Resident left alone on the toilet fell and hit head","paragraphs":["M755: Care plan not followed; resident injured / A resident with Alzheimer's disease, at high risk for falls, was never to be left alone in the bathroom. On July 7, 2023, an aide left the resident on the toilet, and the resident was found on the floor with blood under the head, a large bump and scrape on the forehead, a skin tear, and a bruised elbow."],"link":"https://drive.google.com/file/d/164lUjOLZa8eXSxpUgrrN3HQquK_4a39L/view"},{"date":"2023-02-03","type":"Off-site review","no_findings":true,"tier":null,"headline":"Problems from the last inspection were corrected","paragraphs":[],"link":"https://drive.google.com/file/d/19C4rS999HeRkcolLA24WSYjgrh_0lR31/view"}]}}};
